<?php
declare(strict_types=1);
require_once __DIR__.'/ui.php';require_once __DIR__.'/estate_documents.php';
function estateMoney(int $cents):string {$whole=(string)intdiv(abs($cents),100);return ($cents<0?'-':'').preg_replace('/\B(?=(\d{3})+(?!\d))/','.',$whole).','.str_pad((string)(abs($cents)%100),2,'0',STR_PAD_LEFT);}
function estateInputMoney(int $cents):string {return str_replace('.',',',financeDecimal($cents));}
function estatePage(string $title):void {gszPageStart('Meine Immobilien · '.$title);echo '<nav class="actions"><a href="estate.php">Übersicht</a><a href="estate.php?view=building">Gebäude</a><a href="estate.php?view=unit">Wohnungen / Flächen</a><a href="estate.php?view=tenant">Mieter</a><a href="estate.php?view=lease">Mietverträge</a><a href="estate.php?view=rent">Mietkonto</a><a href="estate.php?view=payment">Zahlungen / Kaution</a><a href="estate_bank.php">Volksbank-Konten</a><a href="estate.php?view=document">Dokumente</a>'.(is_file(dirname(__DIR__).'/public/estate_settlements.php')?'<a href="estate_settlements.php">Nebenkosten</a>':'').'</nav><p>Eigene Immobilien. Daten und Konten getrennt vom Gebäudeservice/Sparkassenkonto. Bankonlinezugriff nicht verbunden.</p>';}
function estateOptions(array $rows,string $field,string $label,int $selected=0,bool $optional=true):void {echo '<select name="'.e($field).'">';if($optional)echo '<option value="0">Ohne Zuordnung</option>';foreach($rows as $r)echo '<option value="'.(int)$r['id'].'"'.((int)$r['id']===$selected?' selected':'').'>'.e((string)$r[$label]).'</option>';echo '</select>';}
function estateVersion(array $row):void {if(isset($row['row_version']))echo '<input type="hidden" name="row_version" value="'.(int)$row['row_version'].'">';}
function estateRequest():void {echo '<input type="hidden" name="request_key" value="'.bin2hex(random_bytes(32)).'">';}
function estateLists(PDO $pdo):array {$data=[];foreach(['buildings'=>['estate_buildings','name',500],'units'=>['estate_units','label',1000],'tenants'=>['estate_tenants','name',2000],'leases'=>['estate_leases','id',2000]] as $key=>[$table,$order,$max]){$data[$key]=$pdo->query('SELECT * FROM '.$table.' ORDER BY '.$order.',id LIMIT '.($max+1))->fetchAll();if(count($data[$key])>$max)throw new RuntimeException('Stammdatenlimit erreicht; gezielte Suche/Paginierung ergänzen.');}return $data;}
